INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$oswaldo-worcester$$, $$Santo Oswaldo de Worcester$$, $$Bispo de Worcester$$, $$29 de Fevereiro$$, 2, 29, $$Séc. X, Inglaterra$$, $$992, Worcester$$, '{"Worcester"}'::text[], $$Bispo beneditino inglês que reformou os mosteiros e a vida eclesiástica na Inglaterra anglo-saxã, promovendo a cultura e a disciplina monástica.$$, $$Bispo beneditino inglês que reformou os mosteiros e a vida eclesiástica na Inglaterra anglo-saxã, promovendo a cultura e a disciplina monástica.$$, $$[]$$::jsonb, '{"\"A disciplina é a mãe da paz.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{"Reforma","Cultura"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$casimiro$$, $$São Casimiro$$, $$Príncipe da Polônia$$, $$4 de Março$$, 3, 4, $$1458, Cracóvia$$, $$1484, Grodno$$, '{"Polônia","Lituânia"}'::text[], $$Príncipe polonês que viveu em castidade e penitência, recusando a coroa da Hungria por amor à justiça.$$, $$Príncipe polonês que viveu em castidade e penitência, recusando a coroa da Hungria por amor à justiça.$$, $$[]$$::jsonb, '{"\"Prefiro morrer a pecar.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Daniel_Schultz_-_%C5%9Aw._Kazimierz.jpg/440px-Daniel_Schultz_-_%C5%9Aw._Kazimierz.jpg$$, NULL, '{"Castidade","Justiça"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$perpetua-felicidade$$, $$Santas Perpétua e Felicidade$$, $$Mártires de Cartago$$, $$7 de Março$$, 3, 7, $$Séc. II, Cartago$$, $$203, Cartago$$, '{"Mães","Gestantes"}'::text[], $$Perpétua, uma nobre, e Felicidade, sua escrava, foram martirizadas juntas na arena de Cartago por se recusarem a renegar Cristo.$$, $$Perpétua, uma nobre, e Felicidade, sua escrava, foram martirizadas juntas na arena de Cartago por se recusarem a renegar Cristo.$$, $$[]$$::jsonb, '{"\"Somos cristãos; não podemos negar Cristo.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/9/97/Sv._Perpetua_in_Felicita.jpg/440px-Sv._Perpetua_in_Felicita.jpg$$, NULL, '{"Coragem","Fidelidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$joao-deus$$, $$São João de Deus$$, $$Fundador dos Hospitalários$$, $$8 de Março$$, 3, 8, $$1495, Portugal$$, $$1550, Granada$$, '{"Doentes","Hospitais","Enfermeiros"}'::text[], $$Português convertido que fundou a Ordem dos Irmãos Hospitaleiros de São João de Deus, dedicados ao cuidado dos enfermos.$$, $$Português convertido que fundou a Ordem dos Irmãos Hospitaleiros de São João de Deus, dedicados ao cuidado dos enfermos.$$, $$[]$$::jsonb, '{"\"Se olhássemos para o futuro, jamais deixaríamos de fazer o bem.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Murillo_john_of_god.jpg/440px-Murillo_john_of_god.jpg$$, NULL, '{"Caridade","Compaixão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$patricio$$, $$São Patrício$$, $$Apóstolo da Irlanda$$, $$17 de Março$$, 3, 17, $$385, Britânia$$, $$461, Irlanda$$, '{"Irlanda","Engenheiros"}'::text[], $$Britânico escravizado na Irlanda, retornou como missionário e converteu toda a ilha ao cristianismo.$$, $$Britânico escravizado na Irlanda, retornou como missionário e converteu toda a ilha ao cristianismo.$$, $$[]$$::jsonb, '{"\"Cristo comigo, Cristo diante de mim, Cristo atrás de mim.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/6d/Saint_Patrick_Catholic_Church_%28Junction_City%2C_Ohio%29_-_stained_glass%2C_Saint_Patrick_-_detail.jpg/440px-Saint_Patrick_Catholic_Church_%28Junction_City%2C_Ohio%29_-_stained_glass%2C_Saint_Patrick_-_detail.jpg$$, NULL, '{"Perseverança","Evangelização"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
