INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$jose$$, $$São José$$, $$Esposo da Virgem Maria$$, $$19 de Março$$, 3, 19, $$Séc. I a.C., Belém$$, $$Séc. I, Nazaré$$, '{"Trabalhadores","Pais","Igreja Universal"}'::text[], $$Esposo de Maria e pai adotivo de Jesus. Homem justo que obedeceu a Deus em silêncio e fidelidade.$$, $$Esposo de Maria e pai adotivo de Jesus. Homem justo que obedeceu a Deus em silêncio e fidelidade.$$, $$[]$$::jsonb, '{"\"José, filho de Davi, não temas receber Maria, tua esposa.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Guido_Reni_-_St_Joseph_with_the_Infant_Jesus_-_WGA19304.jpg/440px-Guido_Reni_-_St_Joseph_with_the_Infant_Jesus_-_WGA19304.jpg$$, NULL, '{"Silêncio","Obediência","Trabalho"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$anunciacao$$, $$Anunciação do Senhor$$, $$O Verbo se fez carne$$, $$25 de Março$$, 3, 25, NULL, NULL, '{"Vida nascente"}'::text[], $$Solenidade que celebra o anúncio do anjo Gabriel a Maria e a encarnação do Filho de Deus.$$, $$Solenidade que celebra o anúncio do anjo Gabriel a Maria e a encarnação do Filho de Deus.$$, $$[]$$::jsonb, '{"\"Eis a serva do Senhor, faça-se em mim segundo a tua palavra.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/3e/Leonardo_da_Vinci_-_Annunciation_-_WGA12681.jpg/440px-Leonardo_da_Vinci_-_Annunciation_-_WGA12681.jpg$$, NULL, '{"Obediência","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$hugo-grenoble$$, $$São Hugo de Grenoble$$, $$Bispo de Grenoble$$, $$1 de Abril$$, 4, 1, $$1053, França$$, $$1132, Grenoble$$, '{"Grenoble"}'::text[], $$Bispo reformador que acolheu São Bruno e os primeiros cartuxos na Grande Chartreuse.$$, $$Bispo reformador que acolheu São Bruno e os primeiros cartuxos na Grande Chartreuse.$$, $$[]$$::jsonb, '{"\"A solidão é a escola da verdadeira caridade.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/0/05/Francisco_de_Zurbar%C3%A1n_-_San_Hugo_en_el_refectorio_de_los_Cartujos_%28detalle%29.jpg/440px-Francisco_de_Zurbar%C3%A1n_-_San_Hugo_en_el_refectorio_de_los_Cartujos_%28detalle%29.jpg$$, NULL, '{"Reforma","Acolhimento"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$francisco-paula$$, $$São Francisco de Paula$$, $$Fundador dos Mínimos$$, $$2 de Abril$$, 4, 2, $$1416, Paola$$, $$1507, Tours$$, '{"Marinheiros"}'::text[], $$Eremita calabrês que fundou a Ordem dos Mínimos, a mais austera das ordens mendicantes.$$, $$Eremita calabrês que fundou a Ordem dos Mínimos, a mais austera das ordens mendicantes.$$, $$[]$$::jsonb, '{"\"A caridade é a rainha de todas as virtudes.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Fco_de_paula.jpg/440px-Fco_de_paula.jpg$$, NULL, '{"Penitência","Humildade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$isidoro-sevilha$$, $$Santo Isidoro de Sevilha$$, $$Doutor da Igreja$$, $$4 de Abril$$, 4, 4, $$560, Sevilha$$, $$636, Sevilha$$, '{"Internet","Programadores"}'::text[], $$Arcebispo de Sevilha, escreveu as Etimologias, considerada a primeira enciclopédia do Ocidente.$$, $$Arcebispo de Sevilha, escreveu as Etimologias, considerada a primeira enciclopédia do Ocidente.$$, $$[]$$::jsonb, '{"\"O aprendizado é uma jornada, não um destino.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Isidor_von_Sevilla.jpeg/440px-Isidor_von_Sevilla.jpeg$$, NULL, '{"Sabedoria","Erudição"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
