INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$joao-batista-salle$$, $$São João Batista de La Salle$$, $$Padroeiro dos Educadores$$, $$7 de Abril$$, 4, 7, $$1651, Reims$$, $$1719, Rouen$$, '{"Professores","Educadores"}'::text[], $$Sacerdote francês que fundou os Irmãos das Escolas Cristãs e revolucionou a educação popular.$$, $$Sacerdote francês que fundou os Irmãos das Escolas Cristãs e revolucionou a educação popular.$$, $$[]$$::jsonb, '{"\"Para educar as crianças, é preciso primeiro amá-las.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/De_La_Salle.jpg/440px-De_La_Salle.jpg$$, NULL, '{"Educação","Caridade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$liduina$$, $$Santa Liduína$$, $$Padroeira dos Patinadores$$, $$14 de Abril$$, 4, 14, $$1380, Schiedam, Holanda$$, $$1433, Schiedam$$, '{"Patinadores","Doentes crônicos"}'::text[], $$Jovem holandesa que sofreu um grave acidente aos 15 anos e passou o resto da vida acamada, oferecendo seus sofrimentos pela conversão das almas.$$, $$Jovem holandesa que sofreu um grave acidente aos 15 anos e passou o resto da vida acamada, oferecendo seus sofrimentos pela conversão das almas.$$, $$[]$$::jsonb, '{"\"O sofrimento aceito por amor pode salvar almas.\""}'::text[], $$mystic$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Lidwina.jpg/440px-Lidwina.jpg$$, NULL, '{"Paciência","Oferecimento"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$bernadette$$, $$Santa Bernadette Soubirous$$, $$Vidente de Lourdes$$, $$16 de Abril$$, 4, 16, $$1844, Lourdes$$, $$1879, Nevers$$, '{"Doentes","Pastores"}'::text[], $$Jovem camponesa que testemunhou 18 aparições de Nossa Senhora na gruta de Massabielle em Lourdes.$$, $$Jovem camponesa que testemunhou 18 aparições de Nossa Senhora na gruta de Massabielle em Lourdes.$$, $$[]$$::jsonb, '{"\"Não me prometeram felicidade neste mundo, mas no outro.\""}'::text[], $$mystic$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Bernadette_Soubirous_1_publicdomain.jpg/440px-Bernadette_Soubirous_1_publicdomain.jpg$$, NULL, '{"Simplicidade","Obediência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$expedito$$, $$Santo Expedito$$, $$Padroeiro das Causas Urgentes$$, $$19 de Abril$$, 4, 19, $$Séc. III, Armênia$$, $$303, Melitene$$, '{"Causas urgentes","Militares","Estudantes"}'::text[], $$Comandante de uma legião romana martirizado por sua fé. É invocado para problemas que precisam de solução imediata.$$, $$Comandante de uma legião romana martirizado por sua fé. É invocado para problemas que precisam de solução imediata.$$, $$[]$$::jsonb, '{"\"Hodie! — Hoje!\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/1/1d/St_Expeditus.jpg/440px-St_Expeditus.jpg$$, NULL, '{"Prontidão","Fidelidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$anselmo$$, $$Santo Anselmo de Cantuária$$, $$Doutor da Igreja$$, $$21 de Abril$$, 4, 21, $$1033, Aosta$$, $$1109, Cantuária$$, '{"Filósofos"}'::text[], $$Arcebispo de Cantuária e pai da Escolástica, autor do argumento ontológico para a existência de Deus.$$, $$Arcebispo de Cantuária e pai da Escolástica, autor do argumento ontológico para a existência de Deus.$$, $$[]$$::jsonb, '{"\"Creio para entender.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Anselm_of_Canterbury.jpg/440px-Anselm_of_Canterbury.jpg$$, NULL, '{"Fé","Razão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
