INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$jorge$$, $$São Jorge$$, $$O Matador de Dragões$$, $$23 de Abril$$, 4, 23, $$Séc. III, Capadócia$$, $$303, Lídia$$, '{"Soldados","Escoteiros","Inglaterra"}'::text[], $$Soldado romano martirizado na perseguição de Diocleciano. A lenda do dragão simboliza sua vitória sobre o mal.$$, $$Soldado romano martirizado na perseguição de Diocleciano. A lenda do dragão simboliza sua vitória sobre o mal.$$, $$[]$$::jsonb, '{"\"A fé é a armadura que vence todos os inimigos.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/b/b7/Raphael_-_Saint_George_and_the_Dragon_-_Google_Art_Project.jpg/440px-Raphael_-_Saint_George_and_the_Dragon_-_Google_Art_Project.jpg$$, NULL, '{"Coragem","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$marcos-evangelista$$, $$São Marcos Evangelista$$, $$O Evangelista do Leão$$, $$25 de Abril$$, 4, 25, $$Séc. I, Cirene$$, $$68, Alexandria$$, '{"Veneza","Escribas"}'::text[], $$Autor do segundo Evangelho, discípulo de São Pedro. Fundou a Igreja de Alexandria, no Egito.$$, $$Autor do segundo Evangelho, discípulo de São Pedro. Fundou a Igreja de Alexandria, no Egito.$$, $$[]$$::jsonb, '{"\"O início do Evangelho de Jesus Cristo, Filho de Deus.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Andrea_Mantegna_-_St._Mark_the_Evangelist.jpg/440px-Andrea_Mantegna_-_St._Mark_the_Evangelist.jpg$$, NULL, '{"Evangelização"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$catarina-sena$$, $$Santa Catarina de Sena$$, $$Doutora da Igreja$$, $$29 de Abril$$, 4, 29, $$1347, Sena$$, $$1380, Roma$$, '{"Europa","Enfermeiros","Itália"}'::text[], $$Mística e doutora da Igreja, convenceu o Papa a retornar de Avignon a Roma. Autora do Diálogo.$$, $$Mística e doutora da Igreja, convenceu o Papa a retornar de Avignon a Roma. Autora do Diálogo.$$, $$[]$$::jsonb, '{"\"Sê quem Deus quis que fosses e incendiarás o mundo.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/6/6e/Giovanni_Battista_Tiepolo_-_Saint_Catherine_of_Siena.jpg/440px-Giovanni_Battista_Tiepolo_-_Saint_Catherine_of_Siena.jpg$$, NULL, '{"Misticismo","Coragem"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$jose-operario$$, $$São José Operário$$, $$Padroeiro dos Trabalhadores$$, $$1 de Maio$$, 5, 1, NULL, NULL, '{"Trabalhadores"}'::text[], $$Festa instituída por Pio XII em 1955 para celebrar a dignidade do trabalho humano através do exemplo de São José.$$, $$Festa instituída por Pio XII em 1955 para celebrar a dignidade do trabalho humano através do exemplo de São José.$$, $$[]$$::jsonb, '{"\"O trabalho é oração quando feito com amor a Deus.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Guido_Reni_-_St_Joseph_with_the_Infant_Jesus_-_WGA19304.jpg/440px-Guido_Reni_-_St_Joseph_with_the_Infant_Jesus_-_WGA19304.jpg$$, NULL, '{"Trabalho","Silêncio"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$atanasio$$, $$Santo Atanásio$$, $$Defensor da Fé$$, $$2 de Maio$$, 5, 2, $$296, Alexandria$$, $$373, Alexandria$$, '{"Teólogos"}'::text[], $$Bispo de Alexandria que lutou durante toda a vida contra a heresia ariana, sendo exilado cinco vezes.$$, $$Bispo de Alexandria que lutou durante toda a vida contra a heresia ariana, sendo exilado cinco vezes.$$, $$[]$$::jsonb, '{"\"Deus se fez homem para que o homem se tornasse Deus.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/2/2a/Sv_Atanasij_Veliki.jpg/440px-Sv_Atanasij_Veliki.jpg$$, NULL, '{"Perseverança","Ortodoxia"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
