INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$filipe-tiago$$, $$Santos Filipe e Tiago$$, $$Apóstolos$$, $$3 de Maio$$, 5, 3, $$Séc. I, Galileia$$, $$Séc. I$$, '{"Chapeleiros"}'::text[], $$Dois dos doze apóstolos celebrados juntos. Filipe trouxe Natanael a Jesus; Tiago é autor de uma epístola canônica.$$, $$Dois dos doze apóstolos celebrados juntos. Filipe trouxe Natanael a Jesus; Tiago é autor de uma epístola canônica.$$, $$[]$$::jsonb, '{"\"A fé sem obras é morta.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/31/Albrecht_D%C3%BCrer_-_The_Apostles_Philip_and_James_-_WGA07067.jpg/440px-Albrecht_D%C3%BCrer_-_The_Apostles_Philip_and_James_-_WGA07067.jpg$$, NULL, '{"Fé","Obras"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nossa-senhora-fatima$$, $$Nossa Senhora de Fátima$$, $$Rainha do Rosário$$, $$13 de Maio$$, 5, 13, NULL, NULL, '{"Portugal","Paz mundial"}'::text[], $$Em 1917, a Virgem Maria apareceu seis vezes a três pastorinhos em Fátima, Portugal, pedindo oração e penitência.$$, $$Em 1917, a Virgem Maria apareceu seis vezes a três pastorinhos em Fátima, Portugal, pedindo oração e penitência.$$, $$[]$$::jsonb, '{"\"Rezai o terço todos os dias para alcançar a paz no mundo.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Our_Lady_of_F%C3%A1tima.jpg/440px-Our_Lady_of_F%C3%A1tima.jpg$$, NULL, '{"Oração","Penitência"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$matias$$, $$São Matias$$, $$O Apóstolo Escolhido$$, $$14 de Maio$$, 5, 14, $$Séc. I, Judeia$$, $$Séc. I$$, '{"Carpinteiros"}'::text[], $$Escolhido por sorteio para substituir Judas Iscariotes como o décimo segundo apóstolo.$$, $$Escolhido por sorteio para substituir Judas Iscariotes como o décimo segundo apóstolo.$$, $$[]$$::jsonb, '{"\"A sorte do Senhor caiu sobre mim.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Peter_Paul_Rubens_-_St_Matthias_-_WGA20202.jpg/440px-Peter_Paul_Rubens_-_St_Matthias_-_WGA20202.jpg$$, NULL, '{"Disponibilidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$visitacao$$, $$Visitação de Nossa Senhora$$, $$Maria visita Isabel$$, $$31 de Maio$$, 5, 31, NULL, NULL, '{"Grávidas"}'::text[], $$Festa que celebra a visita de Maria a sua prima Isabel, quando o Magnificat foi proclamado.$$, $$Festa que celebra a visita de Maria a sua prima Isabel, quando o Magnificat foi proclamado.$$, $$[]$$::jsonb, '{"\"A minha alma glorifica o Senhor.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Mariotto_Albertinelli_-_Visitation_-_WGA0413.jpg/440px-Mariotto_Albertinelli_-_Visitation_-_WGA0413.jpg$$, NULL, '{"Serviço","Alegria"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$justino$$, $$São Justino Mártir$$, $$Filósofo e Mártir$$, $$1 de Junho$$, 6, 1, $$100, Nablus$$, $$165, Roma$$, '{"Filósofos"}'::text[], $$Filósofo pagão convertido, escreveu as primeiras Apologias do cristianismo e foi martirizado em Roma.$$, $$Filósofo pagão convertido, escreveu as primeiras Apologias do cristianismo e foi martirizado em Roma.$$, $$[]$$::jsonb, '{"\"Encontrei na filosofia cristã a única verdadeira filosofia.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Justin_Martyr.jpg/440px-Justin_Martyr.jpg$$, NULL, '{"Verdade","Coragem"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
