INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$marcelo-matias$$, $$Santos Marcelino e Pedro$$, $$Mártires de Roma$$, $$2 de Junho$$, 6, 2, $$Séc. III, Roma$$, $$304, Roma$$, '{"Roma"}'::text[], $$Sacerdote e exorcista martirizados durante a perseguição de Diocleciano. Mencionados no Cânon Romano.$$, $$Sacerdote e exorcista martirizados durante a perseguição de Diocleciano. Mencionados no Cânon Romano.$$, $$[]$$::jsonb, '{"\"Cristo é nossa força na perseguição.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Fra_Angelico_052.jpg/440px-Fra_Angelico_052.jpg$$, NULL, '{"Fidelidade"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$bonifacio$$, $$São Bonifácio$$, $$Apóstolo da Germânia$$, $$5 de Junho$$, 6, 5, $$675, Inglaterra$$, $$754, Frísia$$, '{"Alemanha","Cervejeiros"}'::text[], $$Monge inglês que evangelizou a Germânia, derrubando o carvalho de Thor. Martirizado na Frísia.$$, $$Monge inglês que evangelizou a Germânia, derrubando o carvalho de Thor. Martirizado na Frísia.$$, $$[]$$::jsonb, '{"\"Não nos deixemos esmagar pelo medo, pois temos ao nosso lado o Deus dos exércitos.\""}'::text[], $$martyr$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/52/Bonifatius_von_Fulda.jpg/440px-Bonifatius_von_Fulda.jpg$$, NULL, '{"Coragem","Evangelização"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$natividade-joao-batista$$, $$Natividade de São João Batista$$, $$O Precursor$$, $$24 de Junho$$, 6, 24, $$Séc. I a.C., Ain Karim$$, $$29 d.C., Maqueronte$$, '{"Florença","Quebec"}'::text[], $$O maior dos profetas, precursor de Cristo. Batizou Jesus no Jordão e morreu decapitado por Herodes.$$, $$O maior dos profetas, precursor de Cristo. Batizou Jesus no Jordão e morreu decapitado por Herodes.$$, $$[]$$::jsonb, '{"\"É preciso que Ele cresça e que eu diminua.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e3/Caravaggio_Baptist_Toledo.jpg/440px-Caravaggio_Baptist_Toledo.jpg$$, NULL, '{"Humildade","Profecia"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$pedro-paulo$$, $$Santos Pedro e Paulo$$, $$Pilares da Igreja$$, $$29 de Junho$$, 6, 29, $$Séc. I, Galileia/Tarso$$, $$64/67, Roma$$, '{"Roma","Papado"}'::text[], $$Os dois maiores apóstolos: Pedro, a pedra sobre a qual a Igreja foi edificada; Paulo, o apóstolo dos gentios.$$, $$Os dois maiores apóstolos: Pedro, a pedra sobre a qual a Igreja foi edificada; Paulo, o apóstolo dos gentios.$$, $$[]$$::jsonb, '{"\"Tu és o Cristo, o Filho do Deus vivo.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/El_Greco_-_Apostles_Peter_and_Paul_-_WGA10537.jpg/440px-El_Greco_-_Apostles_Peter_and_Paul_-_WGA10537.jpg$$, NULL, '{"Fé","Missão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$tomas-apostolo$$, $$São Tomé Apóstolo$$, $$O Apóstolo da Índia$$, $$3 de Julho$$, 7, 3, $$Séc. I, Galileia$$, $$Séc. I, Índia$$, '{"Índia","Arquitetos"}'::text[], $$Apóstolo que duvidou da Ressurreição mas confessou "Meu Senhor e meu Deus!". Evangelizou a Índia.$$, $$Apóstolo que duvidou da Ressurreição mas confessou "Meu Senhor e meu Deus!". Evangelizou a Índia.$$, $$[]$$::jsonb, '{"\"Meu Senhor e meu Deus!\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/The_Incredulity_of_Saint_Thomas-Caravaggio_%281601-2%29.jpg/440px-The_Incredulity_of_Saint_Thomas-Caravaggio_%281601-2%29.jpg$$, NULL, '{"Fé","Missão"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
