INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$bento$$, $$São Bento de Núrsia$$, $$Pai do Monaquismo Ocidental$$, $$11 de Julho$$, 7, 11, $$480, Núrsia$$, $$547, Monte Cassino$$, '{"Europa","Monges","Estudantes"}'::text[], $$Fundador da Ordem de São Bento e autor da Regra de São Bento, documento fundamental do monaquismo ocidental.$$, $$Fundador da Ordem de São Bento e autor da Regra de São Bento, documento fundamental do monaquismo ocidental.$$, $$[]$$::jsonb, '{"\"Ora et Labora — Reza e Trabalha.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Fra_Angelico_031.jpg/440px-Fra_Angelico_031.jpg$$, NULL, '{"Oração","Trabalho","Ordem"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$nossa-senhora-carmo$$, $$Nossa Senhora do Carmo$$, $$Flor do Carmelo$$, $$16 de Julho$$, 7, 16, NULL, NULL, '{"Carmelitas","Marinheiros"}'::text[], $$Devoção mariana ligada à Ordem do Carmelo. A Virgem entregou o escapulário a São Simão Stock.$$, $$Devoção mariana ligada à Ordem do Carmelo. A Virgem entregou o escapulário a São Simão Stock.$$, $$[]$$::jsonb, '{"\"Quem morrer vestindo este escapulário não padecerá o fogo eterno.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/4/4e/Tiepolo_-_Our_Lady_of_Mount_Carmel_and_Saints.jpg/440px-Tiepolo_-_Our_Lady_of_Mount_Carmel_and_Saints.jpg$$, NULL, '{"Devoção","Proteção"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$maria-madalena$$, $$Santa Maria Madalena$$, $$Apóstola dos Apóstolos$$, $$22 de Julho$$, 7, 22, $$Séc. I, Magdala$$, $$Séc. I$$, '{"Convertidos","Perfumistas"}'::text[], $$Discípula fiel de Jesus, testemunha da crucificação e primeira a ver o Senhor Ressuscitado.$$, $$Discípula fiel de Jesus, testemunha da crucificação e primeira a ver o Senhor Ressuscitado.$$, $$[]$$::jsonb, '{"\"Rabbuni! — Mestre!\""}'::text[], $$mystic$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/9/99/Guido_Reni_-_The_Penitent_Magdalene_-_Google_Art_Project.jpg/440px-Guido_Reni_-_The_Penitent_Magdalene_-_Google_Art_Project.jpg$$, NULL, '{"Arrependimento","Amor"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$tiago-maior$$, $$São Tiago Maior$$, $$Apóstolo de Compostela$$, $$25 de Julho$$, 7, 25, $$Séc. I, Galileia$$, $$44, Jerusalém$$, '{"Espanha","Peregrinos"}'::text[], $$Irmão de São João, primeiro apóstolo mártir. Seu sepulcro em Santiago de Compostela é destino de peregrinação.$$, $$Irmão de São João, primeiro apóstolo mártir. Seu sepulcro em Santiago de Compostela é destino de peregrinação.$$, $$[]$$::jsonb, '{"\"Podemos beber do cálice do Senhor.\""}'::text[], $$apostle$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Rembrandt_Harmensz._van_Rijn_-_Apostle_James_-_Google_Art_Project.jpg/440px-Rembrandt_Harmensz._van_Rijn_-_Apostle_James_-_Google_Art_Project.jpg$$, NULL, '{"Zelo","Martírio"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$marta$$, $$Santa Marta$$, $$A Anfitriã de Jesus$$, $$29 de Julho$$, 7, 29, $$Séc. I, Betânia$$, $$Séc. I$$, '{"Cozinheiros","Hoteleiros"}'::text[], $$Irmã de Maria e Lázaro, acolheu Jesus em sua casa. Confessou: "Tu és o Cristo, o Filho de Deus."$$, $$Irmã de Maria e Lázaro, acolheu Jesus em sua casa. Confessou: "Tu és o Cristo, o Filho de Deus."$$, $$[]$$::jsonb, '{"\"Sim, Senhor, eu creio que tu és o Cristo.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/Vermeer_-_Christ_in_the_House_of_Martha_and_Mary.jpg/440px-Vermeer_-_Christ_in_the_House_of_Martha_and_Mary.jpg$$, NULL, '{"Hospitalidade","Fé"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
