INSERT INTO public.saints (id, name, title, feast_day, feast_month, feast_day_num, born, died, patron_of, bio, full_bio, works, quotes, category, image, prayer, virtues, bible_refs, catechism_refs, church_doc_refs) VALUES
($$afonso-liguori$$, $$Santo Afonso de Ligório$$, $$Doutor da Igreja$$, $$1 de Agosto$$, 8, 1, $$1696, Nápoles$$, $$1787, Pagani$$, '{"Moralistas","Confessores"}'::text[], $$Fundador dos Redentoristas e grande moralista, autor das Glórias de Maria.$$, $$Fundador dos Redentoristas e grande moralista, autor das Glórias de Maria.$$, $$[]$$::jsonb, '{"\"Quem reza se salva, quem não reza se condena.\""}'::text[], $$doctor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Alfonso_Maria_de_Ligorio.jpg/440px-Alfonso_Maria_de_Ligorio.jpg$$, NULL, '{"Misericórdia","Zelo"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$transfiguracao$$, $$Transfiguração do Senhor$$, $$A Glória de Cristo$$, $$6 de Agosto$$, 8, 6, NULL, NULL, '{"Contemplação"}'::text[], $$Festa que celebra quando Jesus revelou sua glória divina a Pedro, Tiago e João no Monte Tabor.$$, $$Festa que celebra quando Jesus revelou sua glória divina a Pedro, Tiago e João no Monte Tabor.$$, $$[]$$::jsonb, '{"\"Este é o meu Filho amado. Escutai-o.\""}'::text[], $$confessor$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/51/Transfiguration_Raphael.jpg/440px-Transfiguration_Raphael.jpg$$, NULL, '{"Contemplação"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$domingos$$, $$São Domingos de Gusmão$$, $$Fundador dos Dominicanos$$, $$8 de Agosto$$, 8, 8, $$1170, Caleruega$$, $$1221, Bolonha$$, '{"Astrônomos","Pregadores"}'::text[], $$Fundador da Ordem dos Pregadores (Dominicanos), propagou o Rosário como arma espiritual.$$, $$Fundador da Ordem dos Pregadores (Dominicanos), propagou o Rosário como arma espiritual.$$, $$[]$$::jsonb, '{"\"Não tenhais medo, porque a Mãe de Deus está convosco.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Fra_Angelico_-_Saint_Dominic_-_Google_Art_Project.jpg/440px-Fra_Angelico_-_Saint_Dominic_-_Google_Art_Project.jpg$$, NULL, '{"Pregação","Oração"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$clara-assis$$, $$Santa Clara de Assis$$, $$Fundadora das Clarissas$$, $$11 de Agosto$$, 8, 11, $$1194, Assis$$, $$1253, Assis$$, '{"Televisão","Bordadeiras"}'::text[], $$Seguidora de São Francisco, fundou a Ordem das Damas Pobres (Clarissas), dedicada à pobreza e contemplação.$$, $$Seguidora de São Francisco, fundou a Ordem das Damas Pobres (Clarissas), dedicada à pobreza e contemplação.$$, $$[]$$::jsonb, '{"\"Olhai para o espelho da perfeição, que é Cristo.\""}'::text[], $$founder$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Simone_Martini_047.jpg/440px-Simone_Martini_047.jpg$$, NULL, '{"Pobreza","Contemplação"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb),
($$assuncao$$, $$Assunção de Nossa Senhora$$, $$Glória de Maria$$, $$15 de Agosto$$, 8, 15, NULL, NULL, '{"Humanidade"}'::text[], $$Solenidade que celebra a elevação de Maria ao Céu em corpo e alma, dogma definido por Pio XII em 1950.$$, $$Solenidade que celebra a elevação de Maria ao Céu em corpo e alma, dogma definido por Pio XII em 1950.$$, $$[]$$::jsonb, '{"\"Todas as gerações me chamarão bem-aventurada.\""}'::text[], $$virgin$$, $$https://upload.wikimedia.org/wikipedia/commons/thumb/f/f7/Guido_Reni_-_The_Assumption_of_the_Virgin_Mary_-_Google_Art_Project.jpg/440px-Guido_Reni_-_The_Assumption_of_the_Virgin_Mary_-_Google_Art_Project.jpg$$, NULL, '{"Glória","Pureza"}'::text[], $$[]$$::jsonb, '{}'::integer[], $$[]$$::jsonb)
